    {
        "id": "code-py-086",
        "category": "code",
        "language": "python",
        "title": "Topological Depth-First Order",
        "text": "def dfs_postorder(graph: dict[str, list[str]], roots: list[str]) -> list[str]:\n    visited: set[str] = set()\n    order: list[str] = []\n\n    def visit(u: str) -> None:\n        visited.add(u)\n        for v in graph.get(u, []):\n            if v not in visited:\n                visit(v)\n        order.append(u)\n\n    for r in roots:\n        if r not in visited:\n            visit(r)\n    return list(reversed(order))",
        "difficulty": "medium",
        "source": "Algorithms in Python",
        "license": "MIT",
        "author": "Open Source Community",
    },
