    {
        "id": "code-js-083",
        "category": "code",
        "language": "javascript",
        "title": "Standard Deviation Stats",
        "text": "export function standardDeviation(nums) {\n  if (nums.length === 0) return 0;\n  const mean = nums.reduce((a, b) => a + b, 0) / nums.length;\n  const variance = nums.reduce((acc, x) => acc + (x - mean) ** 2, 0) / nums.length;\n  return Math.sqrt(variance);\n}",
        "difficulty": "easy",
        "source": "JavaScript Analytics",
        "license": "MIT",
        "author": "JavaScript Open Source",
    },
