    {
        "id": "code-sql-001",
        "category": "code",
        "language": "sql",
        "title": "Window Function Ranking",
        "text": "SELECT department_id, employee_id, salary,\n       RANK() OVER (PARTITION BY department_id ORDER BY salary DESC) AS rank_in_dept\nFROM employees\nWHERE status = 'ACTIVE'\nORDER BY department_id, rank_in_dept;",
        "difficulty": "medium",
        "source": "SQL Standards Reference",
        "license": "Apache-2.0",
        "author": "SQL Community",
    },
    {
        "id": "code-sql-002",
        "category": "code",
        "language": "sql",
        "title": "Common Table Expression (CTE)",
        "text": "WITH monthly_revenue AS (\n    SELECT DATE_TRUNC('month', order_date) AS order_month,\n           SUM(total_amount) AS revenue\n    FROM customer_orders\n    GROUP BY 1\n)\nSELECT order_month, revenue,\n       LAG(revenue) OVER (ORDER BY order_month) AS prev_month\nFROM monthly_revenue;",
        "difficulty": "medium",
        "source": "PostgreSQL Analytics Tutorials",
        "license": "Apache-2.0",
        "author": "Database Engineers",
    },
    {
        "id": "code-sql-003",
        "category": "code",
        "language": "sql",
        "title": "Recursive CTE Org Hierarchy",
        "text": "WITH RECURSIVE org_tree AS (\n    SELECT employee_id, manager_id, full_name, 0 AS depth\n    FROM employees\n    WHERE manager_id IS NULL\n    UNION ALL\n    SELECT e.employee_id, e.manager_id, e.full_name, t.depth + 1\n    FROM employees e\n    JOIN org_tree t ON e.manager_id = t.employee_id\n)\nSELECT employee_id, full_name, depth FROM org_tree ORDER BY depth, full_name;",
        "difficulty": "hard",
        "source": "SQL Recursive Queries Reference",
        "license": "Apache-2.0",
        "author": "SQL Community",
    },
    {
        "id": "code-sql-004",
        "category": "code",
        "language": "sql",
        "title": "Rolling 7-Day Average",
        "text": "SELECT metric_date, daily_active_users,\n       ROUND(AVG(daily_active_users) OVER (\n           ORDER BY metric_date\n           ROWS BETWEEN 6 PRECEDING AND CURRENT ROW\n       ), 2) AS rolling_7d_avg\nFROM daily_usage_stats\nORDER BY metric_date;",
        "difficulty": "medium",
        "source": "SQL Time-Series Analytics",
        "license": "Apache-2.0",
        "author": "Database Engineers",
    },
    {
        "id": "code-sql-005",
        "category": "code",
        "language": "sql",
        "title": "Cohort Retention Pivot Query",
        "text": "SELECT cohort_month,\n       COUNT(DISTINCT CASE WHEN months_since_signup = 0 THEN user_id END) AS m0,\n       COUNT(DISTINCT CASE WHEN months_since_signup = 1 THEN user_id END) AS m1,\n       COUNT(DISTINCT CASE WHEN months_since_signup = 3 THEN user_id END) AS m3\nFROM user_activity_cohorts\nGROUP BY cohort_month\nORDER BY cohort_month;",
        "difficulty": "medium",
        "source": "Product Analytics SQL Patterns",
        "license": "Apache-2.0",
        "author": "Database Engineers",
    },
    {
        "id": "code-sql-006",
        "category": "code",
        "language": "sql",
        "title": "Upsert on Conflict Update",
        "text": "INSERT INTO feature_flags (flag_key, enabled, updated_at)\nVALUES ('dark_mode_v2', TRUE, CURRENT_TIMESTAMP)\nON CONFLICT (flag_key)\nDO UPDATE SET enabled = EXCLUDED.enabled,\n              updated_at = EXCLUDED.updated_at;",
        "difficulty": "easy",
        "source": "PostgreSQL DML Documentation",
        "license": "Apache-2.0",
        "author": "SQL Community",
    },
    {
        "id": "code-sql-007",
        "category": "code",
        "language": "sql",
        "title": "Top N Per Category with Dense Rank",
        "text": "WITH ranked_products AS (\n    SELECT category_id, product_name, units_sold,\n           DENSE_RANK() OVER (PARTITION BY category_id ORDER BY units_sold DESC) AS rnk\n    FROM product_sales\n)\nSELECT category_id, product_name, units_sold\nFROM ranked_products\nWHERE rnk <= 3;",
        "difficulty": "medium",
        "source": "SQL Standards Reference",
        "license": "Apache-2.0",
        "author": "SQL Community",
    },
